import { createMiddleware } from "@tanstack/react-start";
import { getRequest } from "@tanstack/react-start/server";
import { authenticateRequest } from "./request-auth";

/**
 * Server-function gate. Validates the bearer token attached by
 * `attachSupabaseAuth` and injects an RLS-bound client, so every handler that
 * uses `context.supabase` is automatically scoped to the caller.
 *
 * Raw route handlers cannot take function middleware — they call
 * `authenticateRequest` directly (see `src/routes/api/chat.ts`).
 */
export const requireSupabaseAuth = createMiddleware({ type: "function" }).server(
  async ({ next }) => {
    const { supabase, userId, claims } = await authenticateRequest(getRequest());
    return next({ context: { supabase, userId, claims } });
  },
);
